import{_ as l,B as o,o as d,c,a8 as i,a,E as r,f as t}from"./chunks/framework.CNIpabDg.js";const g=JSON.parse('{"title":"WASM driver crate","description":"The drivers_wasm crate provides drivers for WebAssembly targets (wasm32).","frontmatter":{"layout":"doc","docType":"explanation","description":"The drivers_wasm crate provides drivers for WebAssembly targets (wasm32)."},"headers":[],"relativePath":"explanation/architecture/drivers/wasm.md","filePath":"explanation/architecture/drivers/wasm.md","lastUpdated":1793145952000}'),h={name:"explanation/architecture/drivers/wasm.md"};function p(u,e,m,b,v,f){const s=o("CodeReference"),n=o("HostReference");return d(),c("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[2]||(e[2]=i('<h1 id="wasm-driver-crate" tabindex="-1">WASM driver crate <a class="header-anchor" href="#wasm-driver-crate" aria-label="Permalink to &quot;WASM driver crate&quot;">​</a></h1><p>The <code>drivers_wasm</code> crate provides drivers for WebAssembly targets (<code>wasm32</code>).</p><p>It offers browser/web runtime integrations such as memory/logging adapters, async execution support, and devices including time, drive, and HTTP client access.</p><h2 id="persistent-drive" tabindex="-1">Persistent drive <a class="header-anchor" href="#persistent-drive" aria-label="Permalink to &quot;Persistent drive&quot;">​</a></h2><p>The browser example uses <code>devices::DriveDevice</code> to open the origin-private file <code>xila_drive.img</code> using OPFS and hold a lifetime Web Lock. This main-thread driver keeps a bounded memory cache (16 MiB in the browser example) and commits snapshots asynchronously through <code>sync().await</code>. Synchronous block writes/flushes update the cache; they do not establish OPFS durability.</p><p>Only dirty disks are saved. Saves are serialized and atomic, with at most one additional disk-sized snapshot rather than a growing queue. Failures leave unsaved changes available for retry; the caller must handle errors. OPFS quota/eviction and abrupt tab termination can still lose data.</p><p>The browser example validates existing MBR/LittleFS data and stops on mount errors instead of reformatting a saved image. See <a href="/explanation/browser-storage.html">Browser storage</a> for the cache/autosave model and <a href="/how-to/reset-browser-storage.html">Reset the browser disk</a> for a deliberate reset.</p><h2 id="canvas-color-conversion" tabindex="-1">Canvas color conversion <a class="header-anchor" href="#canvas-color-conversion" aria-label="Permalink to &quot;Canvas color conversion&quot;">​</a></h2><p>When Xila renders a dirty rectangle to browser Canvas <code>ImageData</code>, its little-endian XRGB8888 buffer must be converted from byte order BGRA-like (<code>B,G,R,X</code>) to the Canvas <code>R,G,B,A</code> order. The SIMD converter now handles trailing complete pixels after 16-byte vector chunks instead of copying their bytes unchanged (Core #403). This matters for rectangles whose pixel count is not divisible by four; it does not change the guest graphics ABI or introduce a new graphics capability.</p>',9)),a("ul",null,[a("li",null,[r(s,{repo:"platforms",path:"drivers/wasm/src/devices/graphics/canvas_screen.rs"}),e[0]||(e[0]=t(" — browser framebuffer conversion and dirty rectangles.",-1))])]),e[3]||(e[3]=i('<h2 id="browser-audio" tabindex="-1">Browser audio <a class="header-anchor" href="#browser-audio" aria-label="Permalink to &quot;Browser audio&quot;">​</a></h2><p>The browser example mounts <code>/devices/audio/playback</code> only after an explicit <strong>Enable audio</strong> user gesture. This starts the Web Audio context in accordance with browser autoplay restrictions. The <a href="/explanation/architecture/executables/synth.html">Synth guest</a> can retry audio initialization without requiring an OS restart.</p><h2 id="browser-capabilities" tabindex="-1">Browser capabilities <a class="header-anchor" href="#browser-capabilities" aria-label="Permalink to &quot;Browser capabilities&quot;">​</a></h2><p>OPFS, <code>FileSystemFileHandle.createWritable</code>, and Web Locks require an appropriate browser and localhost/HTTPS. Only one Xila tab can hold the disk lock. The HTTP device uses Fetch and follows browser restrictions such as CORS; it does not expose raw sockets or provide the Xila network manager.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><a href="/explanation/architecture/subsystems/memory.html">Memory</a></li><li><a href="/explanation/architecture/subsystems/graphics.html">Graphics</a></li><li><a href="/explanation/architecture/subsystems/task.html">Task</a></li><li><a href="/explanation/architecture/subsystems/log.html">Log</a></li><li><a href="/explanation/architecture/libraries/shared.html">Shared</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2>',7)),a("ul",null,[a("li",null,[r(n,{repo:"platforms",crate:"drivers_wasm"}),e[1]||(e[1]=t(" — generated Rust API documentation.",-1))]),a("li",null,[r(s,{repo:"platforms",path:"drivers/wasm"})])]),e[4]||(e[4]=a("h2",{id:"see-also",tabindex:"-1"},[t("See also "),a("a",{class:"header-anchor",href:"#see-also","aria-label":'Permalink to "See also"'},"​")],-1)),e[5]||(e[5]=a("ul",null,[a("li",null,[a("a",{href:"/explanation/architecture/drivers.html"},"Drivers")]),a("li",null,[a("a",{href:"/explanation/architecture/drivers/core.html"},"Core driver crate")])],-1))])}const y=l(h,[["render",p]]);export{g as __pageData,y as default};
